const amazonAssociates=require('./amazon-associates');
const {categories,products}=require('../data');
const {brands}=require('./routes');
const {categoryGlyph}=require('./brand-v7');

const esc=value=>String(value??'').replace(/[&<>"']/g,char=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[char]));

const HOME_CATEGORIES=[
  ['coffee-machines','Coffee machines','Workflow, milk systems and the right level of control'],
  ['air-fryers','Air fryers','Capacity, basket layout and cooking versatility'],
  ['robot-vacuums','Robot vacuums','Pet hair, mopping and station automation'],
  ['wireless-headphones','Wireless headphones','Noise cancellation, comfort and battery life'],
  ['computer-monitors','Computer monitors','Resolution, connectivity and work or gaming fit'],
  ['office-chairs','Office chairs','Adjustability, body fit and all-day comfort factors'],
  ['smartwatches','Smartwatches','Phone ecosystem, health features and battery life'],
  ['air-purifiers','Air purifiers','Room size, filtration and quiet operation'],
  ['mesh-wifi-systems','Mesh Wi-Fi','Coverage, backhaul and device-load requirements'],
  ['portable-power-stations','Portable power stations','Capacity, output and recharge speed'],
  ['luggage','Luggage','Cabin size, weight and construction trade-offs'],
  ['tablets','Tablets','Ecosystem, portability and keyboard or stylus needs']
];

function searchForm(){
  return `<form class="global-search apg-home-search-v9" action="/search/" method="get" role="search" data-search-shell><svg viewBox="0 0 24 24" aria-hidden="true"><circle cx="11" cy="11" r="7"></circle><path d="m20 20-4-4"></path></svg><label class="sr-only" for="apgHomeSearchV9">Search Australian Product Guide</label><input id="apgHomeSearchV9" data-site-search name="q" type="search" placeholder="Search a product, category or comparison" autocomplete="off" aria-autocomplete="list" aria-controls="apgHomeSearchV9Suggestions" aria-expanded="false"><button type="submit">Search</button><div id="apgHomeSearchV9Suggestions" class="search-suggestions" data-search-suggestions role="listbox" hidden></div></form>`;
}

function categoryTile([slug,label,copy]){
  return `<a class="apg-home-category-v9" href="/categories/${esc(slug)}/"><span class="apg-home-category-icon-v9" aria-hidden="true">${categoryGlyph(slug)}</span><span><strong>${esc(label)}</strong><small>${esc(copy)}</small></span><b aria-hidden="true">→</b></a>`;
}

function journeyCard(number,title,copy,url,cta){
  return `<article class="apg-home-journey-v9"><span>${number}</span><h3>${esc(title)}</h3><p>${esc(copy)}</p><a href="${url}">${esc(cta)} <b aria-hidden="true">→</b></a></article>`;
}

function researchCard(label,title,copy,url,secondaryUrl,secondaryLabel){
  return `<article class="apg-home-research-v9"><span>${esc(label)}</span><h3><a href="${url}">${esc(title)}</a></h3><p>${esc(copy)}</p><div><a href="${url}">Explore research</a><a href="${secondaryUrl}">${esc(secondaryLabel)}</a></div></article>`;
}

function homeMain(){
  const categoryCount=Object.keys(categories).length;
  const productCount=products.length;
  const brandCount=brands.length;
  return `<main id="main" class="institutional-home-v9">
    <section class="apg-home-hero-v9"><div class="wrap apg-home-hero-grid-v9"><div class="apg-home-hero-copy-v9"><p class="kicker">Independent Australian product guidance</p><h1>Make a better product decision.</h1><p class="lede">Search products, compare meaningful differences or describe what you need. Australian Product Guide explains which options fit, what compromises matter and what evidence supports the decision.</p>${searchForm()}<div class="apg-home-hero-actions-v9"><a class="button" href="/decision-lab/">Describe what I need</a><a class="button secondary" href="/categories/">Browse all categories</a></div><p class="apg-home-hero-note-v9">Built for Australian shoppers · evidence-led · affiliate economics contribute zero recommendation points</p></div><aside class="apg-home-decision-panel-v9" aria-label="How Australian Product Guide helps you decide"><span class="apg-home-panel-label-v9">A clearer path to the right product</span><h2>Start with your situation, not a generic winner.</h2><ol><li><b>01</b><span><strong>Search naturally</strong><small>Products, categories and head-to-head research.</small></span></li><li><b>02</b><span><strong>Compare the trade-offs</strong><small>See what changes the decision for your priorities.</small></span></li><li><b>03</b><span><strong>Inspect the evidence</strong><small>Check sources, freshness and retailer pathways.</small></span></li></ol><a href="/methodology/">See how recommendations work <b aria-hidden="true">→</b></a></aside></div></section>
    <section class="apg-home-proof-v9" aria-label="Australian Product Guide coverage"><div class="wrap"><div><strong>${productCount}</strong><span>maintained products</span></div><div><strong>${categoryCount}</strong><span>populated categories</span></div><div><strong>${brandCount}</strong><span>brands in the maintained set</span></div><div><strong>0</strong><span>commercial points in suitability</span></div></div></section>
    <section class="apg-home-section-v9"><div class="wrap"><div class="apg-home-section-head-v9"><div><p class="kicker">Shop by category</p><h2>Start with what you are buying.</h2><p>Jump into maintained Australian product research without working through a directory of every possible subcategory.</p></div><a href="/categories/">View all ${categoryCount} categories <span aria-hidden="true">→</span></a></div><div class="apg-home-category-grid-v9">${HOME_CATEGORIES.map(categoryTile).join('')}</div></div></section>
    <section class="apg-home-section-v9 apg-home-soft-v9"><div class="wrap"><div class="apg-home-section-head-v9"><div><p class="kicker">Choose how to decide</p><h2>Four ways into the same evidence.</h2><p>Use the route that matches where you are in the purchase, then move between them without losing the decision context.</p></div></div><div class="apg-home-journey-grid-v9">${journeyCard('01','Search','Know the product or problem? Search across products, categories, guides and comparisons.','/search/','Search Australian Product Guide')}${journeyCard('02','Decision Lab','Describe your budget, priorities and deal-breakers in ordinary language.','/decision-lab/','Build an explainable shortlist')}${journeyCard('03','Compare','Put meaningful alternatives side by side and focus on the differences that change the purchase.','/compare/','Compare products')}${journeyCard('04','Buying guides','Understand the category first: what matters, what varies and what to verify before buying.','/guides/','Read buying guides')}</div></div></section>
    <section class="apg-home-section-v9"><div class="wrap"><div class="apg-home-section-head-v9"><div><p class="kicker">Maintained research</p><h2>Useful places to start.</h2><p>These are maintained research pathways, not paid placements or unverified popularity claims.</p></div><a href="/categories/">Explore the full catalogue <span aria-hidden="true">→</span></a></div><div class="apg-home-research-grid-v9">${researchCard('Kitchen','Coffee machines','Compare workflow, milk systems, bench space and how much technique you actually want to learn.','/categories/coffee-machines/','/categories/coffee-machines/finder/','Help me choose')}${researchCard('Home care','Robot vacuums','Separate mopping, pet-hair handling, obstacle avoidance and station automation before paying for features.','/categories/robot-vacuums/','/compare/robot-vacuums/','Compare options')}${researchCard('Audio','Wireless headphones','Balance ANC, comfort, battery life, ecosystem fit and travel priorities.','/categories/wireless-headphones/','/categories/wireless-headphones/finder/','Help me choose')}${researchCard('Kitchen','Air fryers','Choose around household size, basket layout, bench space and the cooking jobs you will actually use.','/categories/air-fryers/','/compare/air-fryers/','Compare options')}</div></div></section>
    <section class="apg-home-trust-v9"><div class="wrap"><div class="apg-home-trust-copy-v9"><p class="kicker">Evidence before hype</p><h2>A comparison site should show its working.</h2><p>Australian Product Guide is designed around explainable product fit. Important claims are tied to maintained evidence, uncertainty is surfaced instead of filled with guesses, and commercial relationships do not increase a product's recommendation score.</p><div><a class="button apg-home-gold-button-v9" href="/methodology/">How we compare</a><a class="button apg-home-dark-secondary-v9" href="/sources/">Source standards</a></div></div><div class="apg-home-trust-points-v9"><article><strong>Evidence-led</strong><p>Primary manufacturer and exact Australian evidence is preferred where practical.</p></article><article><strong>Commercially neutral scoring</strong><p>Affiliate availability, retailer participation and commission contribute zero suitability points.</p></article><article><strong>Australian context</strong><p>Model identity, Australian availability, AUD pricing context and local buying considerations are prioritised.</p></article><article><strong>Truthful testing status</strong><p>Desk research is labelled as desk research. Australian Product Guide does not invent hands-on testing.</p></article></div></div></section>
    <section class="apg-home-section-v9 apg-home-governance-v9"><div class="wrap"><div class="apg-home-section-head-v9"><div><p class="kicker">Trust centre</p><h2>See the standards behind the guidance.</h2><p>Methodology, evidence provenance, corrections and commercial transparency are part of the product experience rather than fine print.</p></div></div><div class="apg-home-governance-grid-v9"><a href="/methodology/"><strong>Methodology</strong><span>How recommendations are built</span><b>→</b></a><a href="/sources/"><strong>Sources & provenance</strong><span>Evidence hierarchy and freshness</span><b>→</b></a><a href="/coverage/"><strong>Coverage</strong><span>Catalogue and retailer scope</span><b>→</b></a><a href="/corrections-policy/"><strong>Corrections</strong><span>How changes are controlled</span><b>→</b></a></div></div></section>
  </main>`;
}

