function sendAsset(req,res){
  res.statusCode=200;
  res.setHeader('Content-Type','text/css; charset=utf-8');
  res.setHeader('Cache-Control','public, max-age=3600');
  res.setHeader('X-Content-Type-Options','nosniff');
  return res.end(req.method==='HEAD'?'':institutionalCss);
}

function enhanceHtml(html,path){
  html=html.replace('<meta name="theme-color" content="#102f4a">','<meta name="theme-color" content="#082735">');
  if(!html.includes('data-institutional-v9='))html=html.replace(/<body([^>]*)>/,'<body$1 data-institutional-v9="true">');
  if(path==='/'&&/<main id="main"[^>]*>[\s\S]*?<\/main>/.test(html))html=html.replace(/<main id="main"[^>]*>[\s\S]*?<\/main>/,homeMain());
  if(!html.includes('/assets/institutional-v9.css'))html=html.replace('</head>','<link rel="stylesheet" href="/assets/institutional-v9.css"></head>');
  return html;
}

module.exports=(req,res)=>{
  let path='';
  try{path=new URL(req.url,'https://australianproductguide.au').pathname}catch{}
  if(path==='/assets/institutional-v9.css')return sendAsset(req,res);
  const originalEnd=res.end.bind(res);
  res.end=(body,...args)=>{
    const type=String(res.getHeader('Content-Type')||'').toLowerCase();
    if(req.method!=='HEAD'&&res.statusCode===200&&typeof body==='string'&&type.startsWith('text/html'))body=enhanceHtml(body,path);
    return originalEnd(body,...args);
  };
  return amazonAssociates(req,res);
};

module.exports.enhanceHtml=enhanceHtml;
